```diff
+	async #startHealthServer(): Promise<void> {
+		const port = Number.parseInt(process.env.OMP_GATEWAY_HEALTH_PORT ?? "7891", 10);
+		const host = "127.0.0.1";
+		const server = Bun.serve({
+			hostname: host,
+			port,
+			async fetch(req) {
+				const url = new URL(req.url);
+				if (req.method === "GET" && url.pathname === "/health") {
+					return Response.json({ status: "ok" });
+				}
+				return Response.json({ ok: false, reason: "not_found" }, { status: 404 });
+			},
+		});
+		this.#healthServer = { stop: () => server.stop(), port: server.port ?? port };
+		logger.debug("Health HTTP endpoint started", {
+			host,
+			port: server.port,
+			endpoint: "GET /health",
+		});
+	}
```
